<script setup>
import Button from 'primevue/button'
import Column from 'primevue/column'
import DataTable from 'primevue/datatable'
import Dialog from 'primevue/dialog'
import InputText from 'primevue/inputtext'
import Message from 'primevue/message'
import Paginator from 'primevue/paginator'
import ProgressSpinner from 'primevue/progressspinner'
import Select from 'primevue/select'
import Tag from 'primevue/tag'
import { computed } from 'vue'
import { usePredictiveMaintenanceLogs } from '@/admin/features/predictiveMaintenance/composables/usePredictiveMaintenanceLogs'

const modes = [{ label: '운영 데이터', value: 'LIVE' }, { label: '시연 데이터', value: 'DEMO' }]
const risks = [{ label: '전체 위험단계', value: 'ALL' }, { label: '정상', value: 'NORMAL' }, { label: '주의', value: 'WARNING' }, { label: '위험', value: 'CRITICAL' }]
const { filters, page, loading, error, selected, selectedShadow, shadowLoading, search, reset, changePage, openDetail } = usePredictiveMaintenanceLogs()
const detailVisible = computed({ get: () => Boolean(selected.value), set: (value) => { if (!value) selected.value = null } })
const showLiveEmptyNotice = computed(() => !loading.value && !error.value && filters.mode === 'LIVE' && page.totalElements === 0)

function dateTime(value) { if (!value) return '—'; const date = new Date(value); return Number.isNaN(date.getTime()) ? String(value) : new Intl.DateTimeFormat('ko-KR', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' }).format(date) }
function number(value, digits = 2) { return value == null ? '—' : Number(value).toFixed(digits) }
function percent(value, digits = 2) { return value == null ? '—' : `${Number(value).toFixed(digits)}%` }
function probability(value) { return value == null ? '미저장' : `${(Number(value) * 100).toFixed(3)}%` }
function riskLabel(value) { return ({ NORMAL: '정상', WARNING: '주의', CRITICAL: '위험' })[value] || '미산정' }
function riskSeverity(value) { return value === 'CRITICAL' ? 'danger' : value === 'WARNING' ? 'warn' : value === 'NORMAL' ? 'success' : 'secondary' }
function yesNo(value) { return value == null ? '—' : Number(value) === 1 ? '예' : '아니오' }
function shadowStatus(value) { return ({ SCORED: 'v2 산정 완료', WARMING_UP: '24시간 수집 중', UNKNOWN_DEVICE: '기준선 미등록', FAILED: '실패' })[value] || '저장 이력 없음' }
</script>

<template>
  <section class="pm-log-page">
    <header class="pm-log-header"><div><p>PM DATA AUDIT</p><h1>예지보전 데이터 로그</h1></div><RouterLink :to="{ name: 'admin-predictive-maintenance', query: { mode: filters.mode } }"><Button label="모니터링 대시보드" icon="pi pi-chart-line" severity="secondary" outlined /></RouterLink></header>

    <Message v-if="showLiveEmptyNotice" severity="warn" :closable="false"><strong>운영 센서 로그가 아직 적재되지 않았습니다.</strong> 운영 데이터는 실장비 수집값이 DB에 저장된 이후 표시됩니다. 준비된 자료를 확인하려면 데이터 구분에서 ‘시연 데이터’를 선택하세요.</Message>
    <Message v-if="error" severity="error" :closable="false">{{ error }}</Message>
    <section class="pm-log-card"><header><div><p>SEARCH CONDITIONS</p><h2>로그 조회 조건</h2></div><strong>총 {{ error ? '—' : page.totalElements.toLocaleString() }}건</strong></header><form class="pm-log-filters" @submit.prevent="search"><label><span>데이터 구분</span><Select v-model="filters.mode" :options="modes" option-label="label" option-value="value" /></label><label><span>장비 ID</span><InputText v-model.trim="filters.equipmentId" placeholder="예: ANT-001" /></label><label><span>위험단계</span><Select v-model="filters.riskLevel" :options="risks" option-label="label" option-value="value" /></label><label><span>시작 시각</span><input v-model="filters.fromAt" type="datetime-local" /></label><label><span>종료 시각</span><input v-model="filters.toAt" type="datetime-local" /></label><div class="pm-log-actions"><Button label="초기화" severity="secondary" outlined type="button" @click="reset" /><Button label="조회" icon="pi pi-search" type="submit" :loading="loading" /></div></form></section>
    <section class="pm-log-card table-card"><header><div><p>SENSOR &amp; PREDICTION</p><h2>시간순 데이터</h2></div><span>{{ filters.mode }} · 최신순</span></header><div v-if="loading&&!page.content.length" class="pm-log-state"><ProgressSpinner /><strong>센서 로그를 불러오고 있습니다.</strong></div><DataTable v-else :value="page.content" data-key="logKey" striped-rows scrollable scroll-height="560px" :table-style="{ minWidth: '84rem' }" class="pm-log-table" @row-click="openDetail($event.data)"><Column field="collectedAt" header="수집 시각" frozen><template #body="{data}"><strong>{{ dateTime(data.collectedAt) }}</strong><small>{{ data.sourceMode }}</small></template></Column><Column field="equipmentId" header="장비"><template #body="{data}"><strong>{{ data.equipmentId }}</strong><small>{{ data.locationId||'위치 미지정' }} · {{ data.equipmentType||'유형 미지정' }}</small></template></Column><Column field="riskLevel" header="판정"><template #body="{data}"><Tag :value="riskLabel(data.riskLevel)" :severity="riskSeverity(data.riskLevel)" /><small>{{ data.riskScore==null?'미저장':`${number(data.riskScore,1)}점` }}</small></template></Column><Column field="successRate" header="성공률"><template #body="{data}">{{ percent(data.successRate) }}</template></Column><Column field="responseTimeMs" header="응답시간"><template #body="{data}">{{ number(data.responseTimeMs,1) }} ms</template></Column><Column field="packetLossRate" header="패킷손실"><template #body="{data}">{{ percent(data.packetLossRate,3) }}</template></Column><Column field="signalStrengthDbm" header="신호"><template #body="{data}">{{ number(data.signalStrengthDbm,1) }} dBm</template></Column><Column field="temperatureC" header="온도"><template #body="{data}">{{ number(data.temperatureC,1) }} °C</template></Column><Column field="retryCount" header="재시도" /><Column field="disconnectCount" header="끊김" /><Column field="errorCount" header="오류" /><template #empty><div class="pm-log-state"><i class="pi pi-database" /><strong>조건에 맞는 데이터 로그가 없습니다.</strong></div></template></DataTable><Paginator v-if="page.totalElements" :first="page.page*page.size" :rows="page.size" :total-records="page.totalElements" :rows-per-page-options="[25,50,100]" @page="changePage" /></section>
    <Dialog v-model:visible="detailVisible" modal header="센서 로그 상세" :style="{width:'min(96vw,1050px)'}"><div v-if="selected" class="pm-log-detail"><header><div><strong>{{ selected.equipmentId }}</strong><span>{{ selected.locationId||'위치 미지정' }} · {{ selected.equipmentType||'장비' }}</span><small>{{ dateTime(selected.collectedAt) }} · {{ selected.logKey }}</small></div><Tag :value="riskLabel(selected.riskLevel)" :severity="riskSeverity(selected.riskLevel)" /></header><section><h3>이전 저장값 · v1 또는 원본</h3><dl><div><dt>위험 점수</dt><dd>{{ selected.riskScore==null?'미산정':`${number(selected.riskScore)} / 100` }}</dd></div><div><dt>원시 확률</dt><dd>{{ probability(selected.rawProbability) }}</dd></div><div><dt>보정 확률</dt><dd>{{ probability(selected.calibratedProbability) }}</dd></div><div><dt>모델 버전</dt><dd>{{ selected.modelVersion||'미저장' }}</dd></div><div><dt>예측 시각</dt><dd>{{ dateTime(selected.predictedAt) }}</dd></div></dl></section><section><h3>주 예측값 · v2</h3><div v-if="shadowLoading" class="pm-log-shadow-state">저장된 v2 판정을 조회하는 중입니다.</div><dl v-else-if="selectedShadow"><div><dt>상태</dt><dd>{{ shadowStatus(selectedShadow.status) }}</dd></div><div><dt>위험 점수</dt><dd>{{ selectedShadow.riskScore==null?'미산정':number(selectedShadow.riskScore)+' / 100' }}</dd></div><div><dt>위험 단계</dt><dd>{{ riskLabel(selectedShadow.riskLevel) }}</dd></div><div><dt>모델 버전</dt><dd>{{ selectedShadow.modelVersion }}</dd></div><div><dt>연속 이력</dt><dd>{{ selectedShadow.historyRows }}시간</dd></div><div><dt>저장 시각</dt><dd>{{ dateTime(selectedShadow.predictedAt) }}</dd></div></dl><div v-else class="pm-log-shadow-state">이 시점의 v2 판정이 아직 저장되지 않았습니다. 대시보드에서 해당 시점을 조회하면 생성됩니다.</div></section><section><h3>원시 센서값</h3><dl><div><dt>트래픽 부하</dt><dd>{{ number(selected.trafficLoad,4) }}</dd></div><div><dt>온도</dt><dd>{{ number(selected.temperatureC,3) }} °C</dd></div><div><dt>전압</dt><dd>{{ number(selected.voltageV,3) }} V</dd></div><div><dt>신호 세기</dt><dd>{{ number(selected.signalStrengthDbm,3) }} dBm</dd></div><div><dt>통신 성공률</dt><dd>{{ percent(selected.successRate,4) }}</dd></div><div><dt>응답시간</dt><dd>{{ number(selected.responseTimeMs,3) }} ms</dd></div><div><dt>재시도</dt><dd>{{ selected.retryCount??'—' }}</dd></div><div><dt>연결 끊김</dt><dd>{{ selected.disconnectCount??'—' }}</dd></div><div><dt>패킷 손실</dt><dd>{{ percent(selected.packetLossRate,4) }}</dd></div><div><dt>오류</dt><dd>{{ selected.errorCount??'—' }}</dd></div><div><dt>정비 후 경과</dt><dd>{{ selected.daysSinceMaintenance??'—' }}일</dd></div></dl></section><section v-if="selected.sourceMode==='DEMO'"><h3>시연 검증 라벨</h3><dl><div><dt>7일 내 고장</dt><dd>{{ yesNo(selected.failureWithin7d) }}</dd></div><div><dt>고장 이벤트</dt><dd>{{ yesNo(selected.failureEvent) }}</dd></div><div><dt>정비 이벤트</dt><dd>{{ yesNo(selected.maintenanceEvent) }}</dd></div><div><dt>잔여수명</dt><dd>{{ selected.rulHours==null?'—':`${number(selected.rulHours,1)}시간` }}</dd></div></dl></section></div></Dialog>
  </section>
</template>

<style scoped>
.pm-log-page{display:grid;gap:1rem;padding:1.25rem;color:#172033}.pm-log-header,.pm-log-card>header,.pm-log-detail>header{display:flex;align-items:center;justify-content:space-between;gap:1rem}.pm-log-header p,.pm-log-card header p{margin:0;color:#2563eb;font-size:.72rem;font-weight:800;letter-spacing:.14em}.pm-log-header h1,.pm-log-card h2{margin:.25rem 0}.pm-log-header span,.pm-log-card header span{color:#697386}.pm-log-card{background:#fff;border:1px solid #e3e8ef;border-radius:16px;padding:1.15rem;box-shadow:0 8px 28px rgba(15,23,42,.05)}.pm-log-filters{display:grid;grid-template-columns:1fr 1.2fr 1fr 1.2fr 1.2fr auto;gap:.8rem;align-items:end;margin-top:1rem}.pm-log-filters label{display:grid;gap:.4rem}.pm-log-filters label>span{font-size:.78rem;font-weight:700;color:#475569}.pm-log-filters input{height:42px;border:1px solid #cbd5e1;border-radius:7px;padding:0 .7rem;font:inherit}.pm-log-actions{display:flex;gap:.5rem}.table-card{overflow:hidden}.pm-log-table :deep(td){white-space:nowrap;cursor:pointer}.pm-log-table strong,.pm-log-table small{display:block}.pm-log-table small{margin-top:.2rem;color:#778196;font-size:.72rem}.pm-log-state{min-height:180px;display:flex;align-items:center;justify-content:center;gap:.7rem;color:#64748b}.pm-log-detail{display:grid;gap:1rem}.pm-log-detail>header{padding-bottom:1rem;border-bottom:1px solid #e5e7eb}.pm-log-detail>header div{display:grid;gap:.2rem}.pm-log-detail>header strong{font-size:1.25rem}.pm-log-detail>header span,.pm-log-detail>header small{color:#64748b}.pm-log-detail section{border:1px solid #e5e7eb;border-radius:12px;padding:1rem}.pm-log-detail h3{margin:0 0 .8rem}.pm-log-detail dl{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:.7rem;margin:0}.pm-log-detail dl div{background:#f8fafc;border-radius:9px;padding:.75rem}.pm-log-detail dt{font-size:.72rem;color:#64748b}.pm-log-detail dd{margin:.3rem 0 0;font-weight:700;word-break:break-all}@media(max-width:1100px){.pm-log-filters{grid-template-columns:repeat(3,1fr)}.pm-log-detail dl{grid-template-columns:repeat(3,1fr)}}@media(max-width:700px){.pm-log-header{align-items:flex-start;flex-direction:column}.pm-log-filters{grid-template-columns:1fr}.pm-log-detail dl{grid-template-columns:repeat(2,1fr)}}
.pm-log-shadow-state{padding:1rem;color:#64748b;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:9px;line-height:1.55}
.pm-log-header h1{font-size:clamp(1.75rem,2.4vw,2.25rem);line-height:1.2;letter-spacing:-.04em}
.pm-log-table :deep(tbody tr){transition:background-color .15s ease}.pm-log-table :deep(tbody tr:hover){background:#eef5ff}
</style>


